function deepFreeze(value) {
  for (const entry of Object.values(value)) Object.freeze(entry);
  return Object.freeze(value);
}

export function sharedToolContract(page, toolType, storefrontTier) {
  const canonicalPage = String(page || '').trim();
  const canonicalType = String(toolType || '').trim();
  const tier = TIER_CONTRACT[String(storefrontTier || '').trim().toLowerCase()];
  if (!tier || SHARED_TOOL_PAGE_TOOL_TYPES[canonicalPage] !== canonicalType) return null;
  const product = SHARED_TOOL_PRODUCTS[canonicalType];
  if (!product) return null;
  return { page: canonicalPage, toolType: canonicalType, storefrontTier: String(storefrontTier).trim().toLowerCase(), paidTier: tier.paidTier, variantId: product[tier.key], sku: tier.sku, price: tier.price };
}

export function sharedToolVariantContract(page, toolType, storefrontTier, expectedVariantId) {
  const contract = sharedToolContract(page, toolType, storefrontTier);
  return contract && contract.variantId === String(expectedVariantId || '').trim() ? contract : null;
}

export function sharedToolPaidOrderContract(page, toolType, paidTier, variantId, sku, price) {
  const normalizedTier = String(paidTier || '').trim().toLowerCase();
  const storefrontTier = normalizedTier === 'premium' ? 'indepth' : normalizedTier === 'medium' ? 'deeper' : normalizedTier === 'standard' ? 'essential' : '';
  const contract = sharedToolContract(page, toolType, storefrontTier);
  const numericPrice = Number(price);
  return contract && contract.paidTier === normalizedTier && contract.variantId === String(variantId || '').trim() && contract.sku === String(sku || '').trim().toUpperCase() && Number.isFinite(numericPrice) && Math.abs(contract.price - numericPrice) <= 0.001 ? contract : null;
}
